std::locale L_default("C");
std::locale L_specific("en_GB");

// Categories where facets will be taken from L_specific
std::locale::category mask = std::locale::numeric | std::locale::monetary;

// Ctor: L_default (other) provides facets unless specified by mask,
// in which case L_specific (one) provides them.
std::locale L_combined(L_default, L_specific, mask);

// Result: L_combined uses GB numeric/monetary formats, 
// but L_default formats for time, collate, etc.
// std::use_facet<std::numpunct<char>>(L_combined); // Example use
// std::use_facet<std::time_put<char>>(L_combined); // Example use (from L_default)
